/**
 * @typedef {{ utteranceId: string, charStart: number, charEnd: number, quote: string }} EvidenceRef
 * @typedef {{ state: 'known'|'partial'|'ambiguous'|'unknown', value?: any, display?: string, candidates?: any[],
 *   uncertainty: string, evidence: EvidenceRef[], clarification?: { ko: string, en: string } }} Slot
 * @typedef {{ id: string, sessionId: string, speakerId: string, speakerLabel: string, speakerKnown: boolean,
 *   text: string, startedAt: string, lang: 'ko'|'en'|'mixed', provenance: string }} Utterance
 * @typedef {{ id: string, kind: 'event'|'task'|'person'|'fact', summary: { ko: string, en: string },
 *   who: Slot, when: Slot, where: Slot, what: Slot, status: string, supersededBy?: string, supersedes?: string[],
 *   evidence: EvidenceRef[], provenance: string, revision: number }} Memory
 * @typedef {{ kind: 'appointment'|'todo', title: string, who?: string, startsAt?: string, endsAt?: string,
 *   where?: string, remindOffsetsMin: number[], sourceMemoryIds: string[] }} ProposalFields
 * @typedef {{ id: string, revision: number, fields: ProposalFields, state: string, missing: string[],
 *   slotUncertainty: Record<string,string>, evidence: EvidenceRef[], readback: { ko: string, en: string },
 *   duplicateOf?: string, actionRecordId?: string }} Proposal
 * @typedef {{ ok: true, json: any, route: string, model: string, ms: number, cached?: boolean }
 *   | { ok: false, route: string, error: { code: string, message: string, retryable: boolean } }} LlmResult
 * @typedef {{ generateJson(req: { system: string, user: string, schemaHint?: string, timeoutMs?: number }): Promise<LlmResult>,
 *   describe(): { route: string, model: string, healthy: boolean|null, lastError?: string } }} Llm
 */

/** Verbatim-quote check used by core for every model-produced EvidenceRef. */
export function isVerbatim(text, quote) {
  return typeof quote === 'string' && quote.length > 0 && text.includes(quote);
}

/** Single display-state rule shared by ui and app glue (CONTRACTS.md section 5). */
export function displayState(record) {
  if (!record) return 'none';
  const { status, mode, verifyLevel } = record;
  if (status === 'completed') {
    if (mode === 'simulated') return 'simulated_completed';
    if (verifyLevel === 'api_readback' || verifyLevel === 'device_readback') return 'completed_external';
    if (verifyLevel === 'user_attested') return 'user_attested';
    return 'unknown_outcome';
  }
  return status;
}

/** Canonical JSON (sorted keys) for preview digests. */
export function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().filter((k) => value[k] !== undefined)
      .map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

/** Demo clock: "today" is the event day unless overridden (QA may inject another). */
export function demoNow() {
  return globalThis.process?.env?.SJ_NOW ?? '2026-11-09T10:30:00+09:00';
}
